"use client";
/* Capy, from the Piixpal shadcn registry. Options: https://piixpal.vercel.app/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Capy(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("capy"); }, []);
  return React.createElement("piix-pal", { "pal": "capy", ...piixAttrs(props) });
}

export default Capy;
